// Loop over input items and add a new field called 'myNewField' to the JSON of each one
for (const item of $input.all()) {

  let movies = []
  for(let m of item.json.data.allScenes){

    let movie = {
      "@type": "VideoObject",
      "headline": m.title,
      "name": m.title || m.files[0]?.basename,
      "url": m.urls,
      "contentUrl": m.files[0]?.path,
    }
    movies.push(movie)

  }


  item.json.movies = movies
}

  return $input.all();

// Loop over input items and add a new field called 'myNewField' to the JSON of each one
for (const item of $input.all()) {

  let systemRecords = []
  for(let m of item.json.records){

    let fragments = m?.["@id"].split('/')
    let id = fragments[fragments.length -1 ]

    let urls = m?.url || ""
    urls = Array.isArray(urls) ? urls : [urls]
    let url = urls?.[0] || undefined

    let r = {      
      "id": id,
      "url": url,
      "urls": urls, 
    }

    systemRecords.push(r)
  }


  item.json.systemRecords = systemRecords
}

return $input.all();

parameters.value:
=mutation MyMutation2 {
  sceneCreate(
    input: {
      url: "{{ $('Config1').item.json.config.url }}"
      file_ids: "{{ $json.data.findFile.id }}"
    }
  ) {
    id
  }
}

=mutation MyMutation3($fieldOptions: [IdentifyFieldOptionsInput!] = { createMissing: true, strategy: OVERWRITE, field: "title" }) {
  metadataIdentify(
    input: {
      sources: {
        source: { scraper_id: "ScrapeWithURL" }
        options: { setCoverImage: true, fieldOptions: $fieldOptions }
      }
      sceneIDs: "{{ $json.config.scene.id }}"
    }
  )

}

=query MyQuery4 {
  findScenes(
    scene_filter: {
      files_filter: {
        path: {
          value: "{{ $json.config.filepath }}"
          modifier: EQUALS
        }
      }
    }
  ) {
    scenes {
      id
    }
  }
}

